/** The reference's extIc(svg, size): resize an icon by rewriting its width and height. */
export const sizedIcon = (svg: string, size: number) => svg.replace(/<svg([^>]*?)\swidth="[^"]*"\s+height="[^"]*"/, `<svg$1 width="${size}" height="${size}"`);

